def __repr__(self) ->str:
    parts = []
    for attribute in 'name', 'description', 'author_name', 'author_email', 'link', 'link_text', 'keywords':
        value = getattr(self, attribute)
        if value is not None:
            parts.append(f'{attribute}={value!r}')
    if self.waypoints:
        parts.append(f'waypoints={len(self.waypoints)}')
    if self.routes:
        parts.append(f'routes={len(self.routes)}')
    if self.tracks:
        parts.append(f'tracks={len(self.tracks)}')
    return f'GPX({", ".join(parts)})'
